import{_ as e,o as s,c as l,a2 as i}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"资源文件","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/resource-files.md","filePath":"authoring/resource-files.md","lastUpdated":null}'),n={name:"authoring/resource-files.md"};function t(o,a,r,p,c,d){return s(),l("div",null,[...a[0]||(a[0]=[i(`<h1 id="资源文件" tabindex="-1">资源文件 <a class="header-anchor" href="#资源文件" aria-label="Permalink to &quot;资源文件&quot;">​</a></h1><p>课程级资源与 Lesson 分离。Lesson 使用稳定 ID 引用词汇、表达和语法点，不在每节课中复制完整资源对象。</p><h2 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assets/courses/&lt;lang&gt;/</span></span>
<span class="line"><span>  vocab.json</span></span>
<span class="line"><span>  expressions.json</span></span>
<span class="line"><span>  grammar_points.json</span></span></code></pre></div><h2 id="词汇" tabindex="-1">词汇 <a class="header-anchor" href="#词汇" aria-label="Permalink to &quot;词汇&quot;">​</a></h2><p>词汇对象至少需要稳定 <code>id</code>、目标语形式和释义。可选内容包括例句、词性、音频引用和附加标签。确切字段以当前应用模型和校验器为准。</p><p>规则：</p><ul><li>相同词项不要因为出现在不同 Lesson 而创建多个 ID。</li><li>同形异义项需要在释义或语法功能确实不同且运行时需要区分时拆分。</li><li>发布后的 ID 不随显示名称调整。</li><li>Lesson 的 <code>wordId</code> 必须指向已有对象。</li></ul><h2 id="表达" tabindex="-1">表达 <a class="header-anchor" href="#表达" aria-label="Permalink to &quot;表达&quot;">​</a></h2><p><code>expressions.json</code> 有独立版本。表达是多词单位、固定搭配或需要整体学习的结构。单个普通词不应为了添加例句而升级为 expression。</p><p>课程重新导入键由课程索引版本与表达版本组合。修改表达语义时同时处理版本。</p><h2 id="语法点" tabindex="-1">语法点 <a class="header-anchor" href="#语法点" aria-label="Permalink to &quot;语法点&quot;">​</a></h2><p>语法点使用稳定 ID 被 Lesson 的 <code>linkedGrammarPointIds</code> 等字段引用。语法点描述规则；练习题仍位于 Lesson 内容中。</p><p>一个语法点应包含：</p><ul><li>可检索标题。</li><li>明确规则范围。</li><li>目标级别或使用条件。</li><li>足够但有限的例子。</li><li>与其它语法点不重叠的边界。</li></ul><h2 id="引用完整性" tabindex="-1">引用完整性 <a class="header-anchor" href="#引用完整性" aria-label="Permalink to &quot;引用完整性&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resource file owns object</span></span>
<span class="line"><span>  &lt;- Lesson references stable id</span></span>
<span class="line"><span>  &lt;- Interaction references stable id</span></span>
<span class="line"><span>  &lt;- validator checks existence</span></span></code></pre></div><p>删除资源前必须先查询所有引用。自动修复可以对齐明确的重复 ID，不得凭相似字符串静默改写引用。</p><h2 id="去重" tabindex="-1">去重 <a class="header-anchor" href="#去重" aria-label="Permalink to &quot;去重&quot;">​</a></h2><p>教材导入使用规范化 key 检测项目内重复和与现有课程碰撞。推荐人工确认：</p><ol><li>比较 term 与 translation。</li><li>检查词性和实际语义。</li><li>选择保留已有 ID 或建立新义项。</li><li>重写草稿引用。</li><li>运行 validate 与 lint。</li></ol><h2 id="变更步骤" tabindex="-1">变更步骤 <a class="header-anchor" href="#变更步骤" aria-label="Permalink to &quot;变更步骤&quot;">​</a></h2><ol><li>修改资源文件。</li><li>更新所有受影响 Lesson 引用。</li><li>运行校验。</li><li>生成内容清单检查规模和孤立项。</li><li>增加相应内容版本。</li><li>在客户端执行重新导入验证。</li></ol><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/authoring/course-layout">课程目录约定</a></li><li><a href="/docs/authoring/lesson-schema">Lesson JSON 结构</a></li><li><a href="/docs/authoring/validation">校验与 Lint</a></li></ul>`,25)])])}const b=e(n,[["render",t]]);export{u as __pageData,b as default};
